using System;using System.Linq;using System.Threading.Tasks;using UnityEngine;using UnityEditor;using AntColony.Units;
public static class Native1112Focus{public static async Task<string> Run(){var all=UnityEngine.Object.FindObjectsByType<MeshyNativeMotionPlayer>(FindObjectsSortMode.None);foreach(var q in all){q.PreviewMotion="Idle_3";q.PreviewPhase=.3f;}var p=all.First();p.transform.position=new Vector3(75,0,75);AntColony.UI.SimulationPause.UserSpeed(0);EditorApplication.isPaused=false;var cc=UnityEngine.Object.FindAnyObjectByType<AntColony.Camera.IsometricCameraController>();if(cc)cc.enabled=false;await Task.Delay(350);var original=p.transform.Find("Kemono");var focus=p.transform.position+original.localPosition+Vector3.up*.85f;var cam=Camera.main;cam.transform.position=focus+original.forward*3+original.right*.8f;cam.transform.LookAt(focus);cam.orthographicSize=1.1f;cam.nearClipPlane=.02f;return p.name;}}
